--- ANSI 16-color palettes, kept in sync with the Ghostty themes so the
--- built-in Neovim terminal matches Ghostty exactly. Index 1 is ANSI 0.
M.ansi = {
  dark = {
    M.dark.ui, -- 0 black
    M.dark.red, -- 1 red
    M.dark.green, -- 2 green
    M.dark.orange, -- 3 yellow (orange reads better than the muted yellow)
    M.dark.blue, -- 4 blue
    M.dark.purple, -- 5 magenta
    M.dark.cyan, -- 6 cyan
    M.dark.tx2, -- 7 white
    M.dark.tx3, -- 8 bright black
    M.dark.red, -- 9 bright red
    M.dark.green, -- 10 bright green
    M.dark.yellow, -- 11 bright yellow
    M.dark.blue, -- 12 bright blue
    M.dark.magenta, -- 13 bright magenta
    M.dark.cyan, -- 14 bright cyan
    M.dark.tx, -- 15 bright white
  },
  light = {
    M.light.tx2, -- 0 black
    M.light.red, -- 1 red
    M.light.green, -- 2 green
    M.light.orange, -- 3 yellow (orange reads better than the muted yellow)
    M.light.blue, -- 4 blue
    M.light.purple, -- 5 magenta
    M.light.cyan, -- 6 cyan
    M.light.ui2, -- 7 white
    M.light.tx3, -- 8 bright black
    M.light.red, -- 9 bright red
    M.light.green, -- 10 bright green
    M.light.yellow, -- 11 bright yellow
    M.light.blue, -- 12 bright blue
    M.light.magenta, -- 13 bright magenta
    M.light.cyan, -- 14 bright cyan
    M.light.tx, -- 15 bright white
